    float lvW(float lv) { return clamp(amzp_reach * 6.0 - lv, 0.0, 1.0) * mix(1.0, 0.35, amzp_falloff); }
    float3 glowAt(float2 uv) {
        float w0 = lvW(0.0), w1 = w0 * lvW(1.0), w2 = w1 * lvW(2.0), w3 = w2 * lvW(3.0), w4 = w3 * lvW(4.0);
        float3 c = soft(1, uv, 1.0 / getTexSize((screen.zw/2.0)));
        if (w0 > 0.0) c += soft(2, uv, 1.0 / getTexSize((screen.zw/4.0))) * w0;
        if (w1 > 0.0) c += soft(3, uv, 1.0 / getTexSize((screen.zw/8.0))) * w1;
        if (w2 > 0.0) c += soft(4, uv, 1.0 / getTexSize((screen.zw/16.0))) * w2;
        if (w3 > 0.0) c += soft(5, uv, 1.0 / getTexSize((screen.zw/32.0))) * w3;
        if (w4 > 0.0) c += soft(6, uv, 1.0 / getTexSize((screen.zw/64.0))) * w4;
        return c;
    }
    float3 glowFast(float2 uv) {
        float w0 = lvW(0.0), w1 = w0 * lvW(1.0), w2 = w1 * lvW(2.0), w3 = w2 * lvW(3.0), w4 = w3 * lvW(4.0);
        return rd(1, uv).rgb + rd(2, uv).rgb * w0 + rd(3, uv).rgb * w1
             + rd(4, uv).rgb * w2 + rd(5, uv).rgb * w3 + rd(6, uv).rgb * w4;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        if (amzPass == 0) {
            float2 h = 0.5 / getTexSize((screen.zw/1.0));
            float4 c = (amzTexture(0, uv + float2(-h.x, -h.y)) + amzTexture(0, uv + float2(h.x, -h.y))
                    + amzTexture(0, uv + float2(-h.x, h.y)) + amzTexture(0, uv + float2(h.x, h.y))) * 0.25;
            float a = c.a;
            float3 col = clamp(c.rgb / max(a, 1e-4), 0.0, 1.0);
            float lum = max(col.r, max(col.g, col.b));
            float k = amzp_litKnee * 0.5;
            float pick = int(amzp_glowSrc) == 1 ? 1.0 : smoothstep(amzp_litFrom - k, amzp_litFrom + k + 1e-4, lum);
            amzOutput = encL(float4(pow(col, float3(2.2)) * a * pick, a * pick));
            return;
        }
        if (amzPass == 1) { amzOutput = shrink(1, uv, 1.0 / getTexSize((screen.zw/2.0))); return; }
        if (amzPass == 2) { amzOutput = shrink(2, uv, 1.0 / getTexSize((screen.zw/4.0))); return; }
        if (amzPass == 3) { amzOutput = shrink(3, uv, 1.0 / getTexSize((screen.zw/8.0))); return; }
        if (amzPass == 4) { amzOutput = shrink(4, uv, 1.0 / getTexSize((screen.zw/16.0))); return; }
        if (amzPass == 5) { amzOutput = shrink(5, uv, 1.0 / getTexSize((screen.zw/32.0))); return; }
        float3 L = glowAt(uv);
        if (amzp_chroma > 0.001) {
            float2 d = uv - 0.5;
            float sp = amzp_chroma * 0.04;
            float3 c0 = glowFast(uv);
            L.r = max(L.r + glowFast(0.5 + d * (1.0 + sp)).r - c0.r, 0.0);
            L.b = max(L.b + glowFast(0.5 + d * (1.0 - sp)).b - c0.b, 0.0);
        }
        float2 szP = getTexSize((screen.zw/1.0));
        float2 eD = min(uv, 1.0 - uv) * szP;
        float fw = max(amzp_borderFade * 0.5 * min(szP.x, szP.y), 1e-3);
        float eF = amzp_borderFade > 0.001 ? smoothstep(0.0, 1.0, clamp(min(eD.x, eD.y) / fw, 0.0, 1.0)) : 1.0;
        float ft = time * amzp_flickSpd, fk = floor(ft), ff = ft - fk;
        float nz = mix(fract(sin(fk * 91.7) * 43758.5453), fract(sin((fk + 1.0) * 91.7) * 43758.5453), ff * ff * (3.0 - 2.0 * ff));
        float flick = 1.0 - clamp(amzp_flickAmt, 0.0, 1.0) * nz;
        float3 light = L * amzp_power * eF * flick;
        float lw = dot(light, float3(0.2126, 0.7152, 0.0722));
        light = max(mix(float3(lw), light, amzp_glowSat), float3(0.0));
        if ((amzp_tintOn>0.5)) light *= mix(float3(1.0), amzp_tintCol.rgb, amzp_tintAmt);
        float hot = max(light.r, max(light.g, light.b));
        light += float3(amzp_coreHeat * 0.25 * hot * hot);
        float3 rolled = (amzp_softHi>0.5) ? (float3(1.0) - exp(-light)) : min(light, float3(1.0));
        float3 glowC = pow(rolled, float3(1.0 / 2.2));
        float4 lay = (amzp_glowOnly>0.5) ? float4(0.0) : amzTexture(0, uv);
        float cover = max(glowC.r, max(glowC.g, glowC.b));
        float3 rgb = (amzp_softHi>0.5) ? lay.rgb + glowC - lay.rgb * glowC : min(lay.rgb + glowC, float3(1.0));
        float alpha = clamp(max(lay.a + cover * (1.0 - lay.a), max(rgb.r, max(rgb.g, rgb.b))), 0.0, 1.0);
        rgb += (fract(sin(dot(uv, float2(12.9898, 78.233))) * 43758.5453) - 0.5) / 255.0;
        amzOutput = float4(clamp(rgb, 0.0, alpha), alpha);
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, uv).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
